// ?GetAdditionalDisconnectsFromUserFile@@YAXPAVPSPlayerStats@@@Z
// partial score=0.55 date=2026-09-10
// Research body excerpt for GetAdditionalDisconnectsFromUserFile @ 0x004DB560.
void GetAdditionalDisconnectsFromUserFile(PSPlayerStats *stats)
{
	BfmePSPlayerStatsLayout &bfmeStats = *reinterpret_cast<BfmePSPlayerStatsLayout *>(stats);
	if (!stats || bfmeStats.id == 0) return;
	if (reinterpret_cast<BfmeGameSpyInfoDisconnectView *>(TheGameSpyInfo)->getAdditionalDisconnects() > 0 &&
		!readAdditionalDisconnectsFromUserFile(bfmeStats.id)) {
		DEBUG_LOG(("Clearing additional disconnects\n"));
		reinterpret_cast<BfmeGameSpyInfoDisconnectView *>(TheGameSpyInfo)->clearAdditionalDisconnects();
	}
	if (reinterpret_cast<BfmeGameSpyInfoDisconnectView *>(TheGameSpyInfo)->getAdditionalDisconnects() < 1) return;
	UserPreferences pref;
	AsciiString userPrefFilename;
	userPrefFilename.format(AsciiString("GeneralsOnline\\MiscPref%d.ini"), bfmeStats.id);
	DEBUG_LOG(("GetAdditionalDisconnectsFromUserFile - reading stats from file %s\n", userPrefFilename.str()));
	pref.UserPreferences::load(userPrefFilename);
	if (pref.find("0") != pref.end()) bfmeStats.desyncs[2] += abs(atoi(pref.find("0")->second.str()));
	if (pref.find("1") != pref.end()) bfmeStats.desyncs[3] += abs(atoi(pref.find("1")->second.str()));
	if (pref.find("2") != pref.end()) bfmeStats.desyncs[4] += abs(atoi(pref.find("2")->second.str()));
	if (pref.find("3") != pref.end()) bfmeStats.discons[2] += abs(atoi(pref.find("3")->second.str()));
	if (pref.find("4") != pref.end()) bfmeStats.discons[3] += abs(atoi(pref.find("4")->second.str()));
	if (pref.find("5") != pref.end()) bfmeStats.discons[4] += abs(atoi(pref.find("5")->second.str()));
}
